window.FitExtraExercises=[{"id":"hands-on-hips-side-bend","name":"Hands-on-hips side bend","category":"back","group":"Sırt & Omurga","sets":"8 each side","icon":"🧘","steps":["Put your hands on your hips and keep your knees soft.","Lean to one side without bending forward.","Come back to center and switch sides."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"overhead-side-stretch-clasped","name":"Clasped overhead side stretch","category":"back","group":"Sırt & Omurga","sets":"20 seconds each side","icon":"🧘","steps":["Clasp your fingers above your head.","Stretch up tall, then lean to one side.","Breathe into your ribs. Switch sides."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"hip-shift-side-stretch","name":"Hip shift side stretch","category":"back","group":"Sırt & Omurga","sets":"6 each side","icon":"🧘","steps":["Put your hands on your hips.","Push your hips to one side and let your upper body lean the other way.","Feel the stretch in your waist. Switch sides."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"standing-trunk-twist","name":"Standing trunk twist","category":"back","group":"Sırt & Omurga","sets":"8 each side","icon":"🧘","steps":["Cross your arms over your chest.","Turn your upper body to one side. Keep your hips facing forward.","Come back to center and turn to the other side."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"loose-twist-arm-swings","name":"Loose twist arm swings","category":"back","group":"Sırt & Omurga","sets":"30 seconds","icon":"🧘","steps":["Let your arms hang loose and keep your knees soft.","Turn your upper body from side to side and let your arms wrap around you.","Keep it soft, like a towel flapping in the wind."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"torso-circles","name":"Torso circles","category":"back","group":"Sırt & Omurga","sets":"5 each direction","icon":"🧘","steps":["Put your hands on your hips and keep your knees soft.","Draw a wide circle with your upper body: forward, to the side, back, and to the other side.","⚠ Keep the circle small at the back. Don't arch hard."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"hip-hinge-arms-crossed","name":"Bodyweight hip hinge","category":"back","group":"Sırt & Omurga","sets":"10 reps","icon":"🧘","steps":["Cross your arms over your chest and keep your knees soft.","Push your butt back and lean forward with a straight back.","Use your butt muscles to come back up to standing.","⚠ Don't round your lower back."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"hinge-reach-forward","name":"Hip hinge with forward reach","category":"back","group":"Sırt & Omurga","sets":"10 reps","icon":"🧘","steps":["Raise your arms straight up.","Lean forward from your hips, keeping your arms in line with your back.","Stop when your back is almost parallel to the floor, then come up.","⚠ If your lower back feels a pull, don't go as low."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"hinge-y-raise","name":"Hinged Y raise","category":"back","group":"Sırt & Omurga","sets":"10 reps","icon":"🧘","steps":["Lean forward from your hips with a straight back and soft knees.","Keep your arms straight and raise them forward and out to the sides, like the letter Y.","Lower them slowly. Keep your back still.","⚠ If your lower back gets tired, stand up straighter."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"hinge-reverse-fly","name":"Hinged reverse fly","category":"back","group":"Sırt & Omurga","sets":"10 reps","icon":"🧘","steps":["Lean forward from your hips and let your arms hang.","Open your arms out to the sides and squeeze your shoulder blades together.","Lower them slowly."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"hinge-row-no-weight","name":"Hinged bodyweight row","category":"back","group":"Sırt & Omurga","sets":"12 reps","icon":"🧘","steps":["Lean forward from your hips and let your arms hang.","Pull your elbows back, close to your body.","Squeeze your shoulder blades together, then slowly let go."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"hinge-swimmer","name":"Hinged swimmer arms","category":"back","group":"Sırt & Omurga","sets":"10 each side","icon":"🧘","steps":["Lean forward from your hips with a straight back.","Reach one arm forward and the other one back.","Switch at a calm pace, like swimming."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"standing-back-extension","name":"Standing back extension","category":"back","group":"Sırt & Omurga","sets":"6 reps","icon":"🧘","steps":["Place your palms on your lower back.","Lift your chest and lean back a little.","Hold for 2 seconds and come back.","⚠ Keep the movement small. If your lower back hurts, stop."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"thoracic-reach-up","name":"Overhead thoracic extension","category":"back","group":"Sırt & Omurga","sets":"8 reps","icon":"🧘","steps":["Raise both arms above your head.","Lift your chest and look up a little.","Keep your belly pulled in. The movement comes from your upper back."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"standing-c-curve","name":"Standing C-curve","category":"back","group":"Sırt & Omurga","sets":"8 reps","icon":"🧘","steps":["Reach your arms straight forward with your fingers clasped.","Push your hands far away and round your upper back.","Bring your chin to your chest. Come back to standing tall."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"round-and-open","name":"Round and open","category":"back","group":"Sırt & Omurga","sets":"8 reps","icon":"🧘","steps":["Hug a big ball: round your back and drop your chin.","Open your arms out to the sides and back, and lift your chest.","Move slowly between the two positions."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"standing-roll-down","name":"Standing roll-down","category":"back","group":"Sırt & Omurga","sets":"5 reps","icon":"🧘","steps":["Keep your knees soft. Drop your chin to your chest.","Roll your back down one vertebra at a time, arms hanging.","Roll back up slowly the same way, with your head coming up last.","⚠ Only go as far down as feels comfortable. Don't lock your knees."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"half-sun-salute","name":"Half sun salutation","category":"back","group":"Sırt & Omurga","sets":"6 reps","icon":"🧘","steps":["Raise your arms overhead and stretch up tall.","Fold forward from your hips with soft knees, letting your arms come down.","Come up with a straight back and bring your arms back overhead.","⚠ You don't have to reach the floor. Bend your knees as much as you need."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"standing-pelvic-tilt","name":"Standing pelvic tilt","category":"back","group":"Sırt & Omurga","sets":"10 reps","icon":"🧘","steps":["Keep your knees soft and put your hands on your hips.","Tip your pelvis forward and back, like a bowl.","Your upper body barely moves."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"posture-reset","name":"Posture reset","category":"back","group":"Sırt & Omurga","sets":"8 reps","icon":"🧘","steps":["Start slouched like you're at a computer: back rounded, head forward.","Grow tall, tuck your chin in, and pull your shoulders back.","Hold for 3 seconds at your full height."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"standing-bird-dog","name":"Standing bird dog","category":"back","group":"Sırt & Omurga","sets":"8 each side","icon":"🧘","steps":["Stand tall with your belly pulled in.","Reach one arm forward and up, and the opposite leg back.","Hold for a second and switch sides.","⚠ You can hold on to a chair for balance."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"standing-knee-hug","name":"Standing knee hug","category":"back","group":"Sırt & Omurga","sets":"5 each side","icon":"🧘","steps":["Lift one knee and hug it to your chest.","Keep your back straight and your other leg steady.","Hold for 3 seconds and switch.","⚠ You can lean on a wall or a chair."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"tall-reach-tiptoes","name":"Tiptoe tall reach","category":"back","group":"Sırt & Omurga","sets":"8 reps","icon":"🧘","steps":["Raise your arms above your head.","Rise up onto your toes and stretch toward the ceiling.","Slowly lower your heels back down.","⚠ If you feel unsteady, keep your feet flat on the floor."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"seated-cat-cow","name":"Seated cat-cow","category":"back","group":"Sırt & Omurga","sets":"8 reps","icon":"🧘","steps":["Sit on the edge of your chair with your hands on your knees.","Round your back and tuck your chin.","Push your chest forward and lift your gaze."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"seated-spinal-twist","name":"Seated spinal twist","category":"back","group":"Sırt & Omurga","sets":"20 seconds each side","icon":"🧘","steps":["Sit up straight with your feet flat on the floor.","Turn your upper body to one side, with one hand on the opposite knee.","Grow taller as you breathe in, and twist a little more as you breathe out."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"seated-side-bend","name":"Seated side bend","category":"back","group":"Sırt & Omurga","sets":"6 each side","icon":"🧘","steps":["Sit up straight with both sides of your bottom on the chair.","Raise one arm overhead and lean to the other side.","Let your other hand reach toward the floor. Switch sides."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"seated-forward-fold","name":"Seated forward fold","category":"back","group":"Sırt & Omurga","sets":"20 seconds","icon":"🧘","steps":["Sit with your legs slightly apart.","Fold forward between your knees and let your arms hang toward the floor.","Let your head relax. Come up slowly, one vertebra at a time.","⚠ If your lower back hurts, fold only halfway."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"seated-back-extension","name":"Seated thoracic extension","category":"back","group":"Sırt & Omurga","sets":"8 reps","icon":"🧘","steps":["Sit with your hands behind your head.","Lift your chest, open your elbows, and look up a little.","Come back to sitting up straight."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"seated-side-reach-down","name":"Seated side reach down","category":"back","group":"Sırt & Omurga","sets":"5 each side","icon":"🧘","steps":["Sit up straight.","Lean to one side and reach your hand toward the floor next to the chair.","Keep your other hand on your thigh. Come up slowly and switch sides."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"balance-single-leg-stand","name":"Single-leg stand","category":"balance","group":"Denge","sets":"20 seconds each leg","icon":"⚖","steps":["⚠ Stand next to a table or wall, with a hand ready to hold on.","Lift one foot a little off the floor, knee bent.","Keep your eyes on one spot in front of you. Switch legs."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"balance-foot-behind-hold","name":"Single-leg stand, foot behind","category":"balance","group":"Denge","sets":"20 seconds each leg","icon":"⚖","steps":["⚠ Stand next to a table or wall.","Bend one knee and lift that foot behind you.","Keep your knees close together. Switch legs."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"balance-knee-raise-hold","name":"Standing knee raise hold","category":"balance","group":"Denge","sets":"5 each leg","icon":"⚖","steps":["⚠ Stand next to a table or wall.","Lift one knee to hip height and hold for 3 seconds.","Lower it slowly and switch legs."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"balance-slow-march","name":"Slow march in place","category":"balance","group":"Denge","sets":"10 each leg","icon":"⚖","steps":["⚠ Stand next to a table or wall.","Lift one knee and pause for a second at the top.","Lower it quietly and lift the other leg."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"tree-pose-kickstand","name":"Kickstand tree pose","category":"balance","group":"Denge","sets":"20 seconds each leg","icon":"⚖","steps":["⚠ Stand next to a table or wall.","Turn one knee out and rest your heel on the other ankle. Keep your toes on the floor.","Hold your hands in front of your chest. Switch legs."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"tree-pose-calf","name":"Tree pose, foot on calf","category":"balance","group":"Denge","sets":"20 seconds each leg","icon":"⚖","steps":["⚠ Stand next to a table or wall.","Place one foot on the inside of your other calf, not on the knee.","Hold your hands in front of your chest. Switch legs."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"tree-pose-arms-up","name":"Tree pose, arms overhead","category":"balance","group":"Denge","sets":"15 seconds each leg","icon":"⚖","steps":["⚠ Stand next to a table or wall.","Place one foot on your other calf.","Raise your arms over your head like branches. Switch legs."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"heel-to-toe-stand","name":"Heel-to-toe stance","category":"balance","group":"Denge","sets":"20 seconds each side","icon":"⚖","steps":["⚠ Stand next to a table or wall.","Place one foot right in front of the other, heel touching toes.","Hold your arms a little out to the sides. Switch which foot is in front."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"heel-to-toe-walk-in-place","name":"Heel-to-toe walk in place","category":"balance","group":"Denge","sets":"10 steps","icon":"⚖","steps":["⚠ Stand next to a table or wall.","Take a small step forward so your heel lands right against the toes of your back foot.","Step back and switch legs. Go slow and stay in control."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"balance-leg-swing-front-back","name":"Front-back leg swings","category":"balance","group":"Denge","sets":"10 each leg","icon":"⚖","steps":["⚠ Keep one hand on a table or wall.","Swing one leg forward and back. Keep it loose.","Keep the movement small and gentle, and your back straight."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"balance-leg-swing-side","name":"Side leg swings","category":"balance","group":"Denge","sets":"10 each leg","icon":"⚖","steps":["⚠ Keep one hand on a table or wall.","Swing one leg out to the side, then back across in front of the other leg.","Keep your body straight. Only the leg moves."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"clock-reach-foot","name":"Foot clock taps","category":"balance","group":"Denge","sets":"5 rounds each leg","icon":"⚖","steps":["⚠ Stand next to a table or wall.","Stand on one leg with the knee slightly bent.","Tap your toes forward, to the side and back, like the hands of a clock."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"clock-reach-arm","name":"Arm clock reach on one leg","category":"balance","group":"Denge","sets":"5 rounds each side","icon":"⚖","steps":["⚠ Stand next to a table or wall.","Stand on one leg.","Reach one arm up, then out on a diagonal, then out to the side, like a clock hand."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"balance-airplane-mild","name":"Gentle airplane","category":"balance","group":"Denge","sets":"5 each leg","icon":"⚖","steps":["⚠ Keep one hand near a table or wall.","Lean forward a little and lift one leg behind you, arms out to the sides.","Only go as far as feels comfortable, with your back straight. Come back up slowly."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"balance-weight-shift-side","name":"Side-to-side weight shift","category":"balance","group":"Denge","sets":"10 each side","icon":"⚖","steps":["⚠ Stand next to a table or wall.","Stand with your feet shoulder-width apart.","Slowly shift your weight onto one leg, then onto the other."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"balance-toe-heel-rock","name":"Toe-heel rock","category":"balance","group":"Denge","sets":"10 reps","icon":"⚖","steps":["⚠ Stand next to a table or wall.","Slowly rise up onto your toes.","Come back down and lift your toes a little, so you stand on your heels."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"balance-heel-raise-hold","name":"Heel raise hold","category":"balance","group":"Denge","sets":"5 reps","icon":"⚖","steps":["⚠ Stand next to a table or wall.","Rise up onto your toes and hold for 5 seconds.","Lower yourself slowly all the way down."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"single-leg-head-turns","name":"Head turns on one leg","category":"balance","group":"Denge","sets":"5 each side","icon":"⚖","steps":["⚠ Stand next to a table or wall.","Stand on one leg.","Slowly turn your head right and left without losing your balance."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"single-leg-arms-overhead","name":"Single-leg arm raise","category":"balance","group":"Denge","sets":"8 each leg","icon":"⚖","steps":["⚠ Stand next to a table or wall.","Stand on one leg.","Raise both arms over your head and lower them slowly."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"balance-side-leg-raise-hold","name":"Side leg raise hold","category":"balance","group":"Denge","sets":"5 each leg","icon":"⚖","steps":["⚠ Keep one hand on a table or wall.","Lift one straight leg out to the side, a little off the floor.","Hold for 3 seconds without leaning your body. Switch legs."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"balance-back-leg-raise-hold","name":"Back leg raise hold","category":"balance","group":"Denge","sets":"5 each leg","icon":"⚖","steps":["⚠ Keep one hand on a table or wall.","Lift one straight leg a little behind you.","Don't arch your back. Hold for 3 seconds and switch legs."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"knee-raise-open-gate","name":"Knee raise and open the gate","category":"balance","group":"Denge","sets":"5 each leg","icon":"⚖","steps":["⚠ Stand next to a table or wall.","Lift one knee in front of you.","Slowly open the knee out to the side, then lower it."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"side-step-and-hold","name":"Side step and balance","category":"balance","group":"Denge","sets":"8 each side","icon":"⚖","steps":["⚠ Stand next to a table or wall.","Take a small step to the side and lift your other foot off the floor.","Hold for 2 seconds and come back."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"single-leg-cross-reach","name":"Cross reach on one leg","category":"balance","group":"Denge","sets":"6 each side","icon":"⚖","steps":["⚠ Stand next to a table or wall.","Lift your left knee and touch it with your right hand.","Lower it and switch sides. Move slowly."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"single-leg-mini-hinge","name":"Mini hinge on one leg","category":"balance","group":"Denge","sets":"5 each leg","icon":"⚖","steps":["⚠ Keep one hand on a table or wall.","Stand on one leg with the knee slightly bent.","Lean forward a little with a straight back, then stand tall again."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"tandem-arm-swings","name":"Heel-to-toe stance with arm swings","category":"balance","group":"Denge","sets":"20 seconds each side","icon":"⚖","steps":["⚠ Stand next to a table or wall.","Place one foot right in front of the other.","Slowly swing your arms forward and back without moving your feet."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"high-knee-march","name":"High-knee march","category":"cardio","group":"Hafif Kardiyo","sets":"30 seconds","icon":"⚡","steps":["Lift one knee up to hip height.","Lower it quietly and switch legs.","Bend your arms and pump them forward and back.","⚠ If your knee or back hurts, lift lower."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"boxer-shuffle","name":"Boxer shuffle","category":"cardio","group":"Hafif Kardiyo","sets":"30 seconds","icon":"⚡","steps":["Keep your knees soft and your fists by your chin.","Shift your weight from foot to foot, lifting one heel at a time.","Take small, light steps with no jumping."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"side-step-arm-swing","name":"Side step with arm swings","category":"cardio","group":"Hafif Kardiyo","sets":"30 seconds","icon":"⚡","steps":["Take a big step to the side and bring the other foot in.","Open your arms out to the sides with each step.","Go back the other way at a steady pace."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"butt-kick-walk","name":"Butt-kick walk","category":"cardio","group":"Hafif Kardiyo","sets":"30 seconds","icon":"⚡","steps":["Stand tall.","Bend one knee and bring your heel toward your butt.","Switch legs in rhythm and swing your arms.","⚠ If your knee hurts, bend it only halfway."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"skater-step-no-hop","name":"Skater step without hop","category":"cardio","group":"Hafif Kardiyo","sets":"10 each side","icon":"⚡","steps":["Like an ice skater, but with no jumping.","Step to the side and reach the other leg back on a diagonal.","Lean forward a little and swing your arms.","⚠ Keep your knee over your foot. Don't let it cave in."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"standing-bicycle-crunch","name":"Standing bicycle crunch","category":"cardio","group":"Hafif Kardiyo","sets":"10 each side","icon":"⚡","steps":["Put your hands behind your head, elbows wide.","Lift one knee and bring the opposite elbow toward it.","Stand back up and switch sides."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"grapevine","name":"Grapevine","category":"cardio","group":"Hafif Kardiyo","sets":"8 times each side","icon":"⚡","steps":["Step to the side.","Cross the other foot behind it.","Step to the side again and bring your feet together. Then go back the other way."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"heel-dig-punch","name":"Heel dig with punch","category":"cardio","group":"Hafif Kardiyo","sets":"30 seconds","icon":"⚡","steps":["Tap your heel forward with your toes up.","At the same time, punch forward with the opposite hand.","Switch sides in rhythm."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"reverse-toe-tap-reach","name":"Back toe tap with overhead reach","category":"cardio","group":"Hafif Kardiyo","sets":"30 seconds","icon":"⚡","steps":["Take a small step back, touching down with just your toes.","At the same time, raise your arms overhead.","Come back and switch legs."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"knee-lift-pull-down","name":"Knee lift with pull-down","category":"cardio","group":"Hafif Kardiyo","sets":"10 each side","icon":"⚡","steps":["Reach your arms up overhead.","Lift one knee and pull your arms down toward it.","Reach back up. You can switch legs each time."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"side-leg-raise-arms","name":"Side leg raise with arms","category":"cardio","group":"Hafif Kardiyo","sets":"10 each side","icon":"⚡","steps":["Stand tall. You can hold a wall for support.","Lift one straight leg out to the side as you raise your arms out to the sides.","Lower slowly and switch sides."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"standing-side-crunch","name":"Standing side crunch","category":"cardio","group":"Hafif Kardiyo","sets":"10 each side","icon":"⚡","steps":["Put your hands behind your head.","Lift one knee out to the side and bring the elbow on that same side toward it.","Come back and switch sides."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"low-front-kick","name":"Low front kick","category":"cardio","group":"Hafif Kardiyo","sets":"10 each side","icon":"⚡","steps":["Keep your fists by your chin.","Kick forward low and with control.","Bring your leg back and switch.","⚠ Don't lock your knee at the end of the kick."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"jab-cross-step","name":"Jab-cross with step","category":"cardio","group":"Hafif Kardiyo","sets":"30 seconds","icon":"⚡","steps":["Put one foot a little forward and keep your knees soft.","Punch with your front hand, then with your back hand as you turn your body.","Pivot on the toes of your back foot."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"standing-uppercuts","name":"Standing uppercuts","category":"cardio","group":"Hafif Kardiyo","sets":"30 seconds","icon":"⚡","steps":["Keep your knees soft and your fists by your chin.","Drive one fist up from below and turn your body a little.","Switch hands in rhythm."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"hamstring-curl-arm-pull","name":"Hamstring curl with arm pull","category":"cardio","group":"Hafif Kardiyo","sets":"10 each side","icon":"⚡","steps":["Reach your arms forward.","Step to the side and bend the other leg back.","At the same time, pull your elbows back, like rowing."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"step-touch-clap","name":"Step touch with clap","category":"cardio","group":"Hafif Kardiyo","sets":"30 seconds","icon":"⚡","steps":["Step to the side.","Bring the other foot in, tap it down, and clap.","Go back the other way."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"calf-raise-arm-swing","name":"Calf raise with arm swing","category":"cardio","group":"Hafif Kardiyo","sets":"20 reps","icon":"⚡","steps":["Stand with your feet hip-width apart.","Rise up onto your toes and swing your arms forward and up.","Lower onto your heels and swing your arms back."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"lateral-shuffle-low","name":"Low lateral shuffle","category":"cardio","group":"Hafif Kardiyo","sets":"30 seconds","icon":"⚡","steps":["Bend your knees a little and lean forward.","Take quick steps to the side without crossing your feet.","Take three steps each way, then come back.","⚠ Don't go too low if your knees hurt."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"march-arm-circles","name":"March with arm circles","category":"cardio","group":"Hafif Kardiyo","sets":"30 seconds","icon":"⚡","steps":["March in place.","Hold your arms out to the sides and draw small circles.","Halfway through, switch the direction of the circles."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"skier-swing","name":"Skier arm swing","category":"cardio","group":"Hafif Kardiyo","sets":"15 reps","icon":"⚡","steps":["Raise your arms overhead.","Bend your knees a little, lean forward, and swing your arms back.","Come back up and bring your arms back overhead.","⚠ Keep your back straight. If your back is sensitive, bend less."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"twist-march","name":"Twisting march","category":"cardio","group":"Hafif Kardiyo","sets":"30 seconds","icon":"⚡","steps":["Bend your arms in front of your chest.","Lift one knee and turn your body toward it.","Switch sides in rhythm."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"standing-climber","name":"Standing mountain climber","category":"cardio","group":"Hafif Kardiyo","sets":"30 seconds","icon":"⚡","steps":["Pretend you are climbing a ladder.","Reach one hand up as you lift the opposite knee.","Pull your hand down and switch."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"fast-feet-small","name":"Fast feet","category":"cardio","group":"Hafif Kardiyo","sets":"20 seconds","icon":"⚡","steps":["Keep your knees soft and lean forward a little.","Take small, quick steps in place on the balls of your feet.","Bend your arms and move them in rhythm."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"cross-knee-tap","name":"Cross-body knee tap","category":"cardio","group":"Hafif Kardiyo","sets":"10 each side","icon":"⚡","steps":["Reach one arm up on a diagonal.","Lift the opposite knee toward the middle of your body and bring your hand down to it.","Come back and switch sides."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"half-jack-arms","name":"Half jacks with arm press","category":"cardio","group":"Hafif Kardiyo","sets":"20 reps","icon":"⚡","steps":["Keep your feet in place and your knees soft.","Raise your arms out to the sides and up overhead, then lower them.","Bend your knees a little with each lift."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"reverse-lunge-knee-drive","name":"Back step to knee drive","category":"cardio","group":"Hafif Kardiyo","sets":"8 each side","icon":"⚡","steps":["Take a small step back and bend your knees a little.","Push off your back foot and drive that knee up high.","Swing your arms opposite to your legs.","⚠ Keep the step short and the dip small, with your front knee over your ankle."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"power-walk-arms-up","name":"March with overhead press","category":"cardio","group":"Hafif Kardiyo","sets":"30 seconds","icon":"⚡","steps":["March in place.","Bring your fists to your shoulders and press both arms up.","Lower them back down every other step."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-march","name":"Seated marching","category":"chair","group":"Sandalyede Egzersiz","sets":"30 seconds","icon":"🪑","steps":["Sit up tall on the edge of the chair.","Lift one knee, then the other, like marching.","Swing your arms to the beat."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-knee-extension","name":"Seated knee extension","category":"chair","group":"Sandalyede Egzersiz","sets":"10 each leg","icon":"🪑","steps":["Sit up tall with your feet flat on the floor.","Straighten one leg out in front and pull your toes toward you.","Hold for 2 seconds and lower slowly.","⚠ If your knee hurts, straighten it only halfway."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-straight-leg-raise","name":"Seated straight leg raise","category":"chair","group":"Sandalyede Egzersiz","sets":"8 each leg","icon":"🪑","steps":["Stretch one leg straight out in front, heel on the floor.","Lift the straight leg up a little.","Hold for 2 seconds and lower slowly."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-ankle-pumps","name":"Seated ankle pumps","category":"chair","group":"Sandalyede Egzersiz","sets":"20 times","icon":"🪑","steps":["Stretch your legs out a little, heels on the floor.","Point your toes away, then pull them back toward you.","Keep a smooth, steady rhythm. Good for blood flow."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-ankle-circles","name":"Seated ankle circles","category":"chair","group":"Sandalyede Egzersiz","sets":"10 each direction","icon":"🪑","steps":["Lift one foot a little off the floor.","Draw circles with your foot.","Do 10 in each direction, then switch feet."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-heel-raises","name":"Seated heel raises","category":"chair","group":"Sandalyede Egzersiz","sets":"15 times","icon":"🪑","steps":["Feet flat on the floor, knees hip-width apart.","Lift your heels and stay up on your toes.","Lower slowly."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-toe-raises","name":"Seated toe raises","category":"chair","group":"Sandalyede Egzersiz","sets":"15 times","icon":"🪑","steps":["Keep your heels on the floor.","Lift the front of your feet up.","Lower slowly."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-heel-toe-rock","name":"Seated heel-toe rock","category":"chair","group":"Sandalyede Egzersiz","sets":"15 times","icon":"🪑","steps":["Feet flat on the floor.","Rise up onto your toes.","Rock back onto your heels and lift your toes."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-heel-taps","name":"Alternating heel taps","category":"chair","group":"Sandalyede Egzersiz","sets":"20 times","icon":"🪑","steps":["Sit up tall.","Reach one leg forward and tap your heel on the floor.","Bring it back and switch legs, to the beat."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-fast-feet","name":"Seated fast feet","category":"chair","group":"Sandalyede Egzersiz","sets":"20 seconds","icon":"🪑","steps":["Sit on the edge of the chair.","Lift and lower your heels quickly, one after the other.","Like running in place, sitting down."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-knees-open-close","name":"Seated knee open and close","category":"chair","group":"Sandalyede Egzersiz","sets":"12 times","icon":"🪑","steps":["Knees together, feet flat on the floor.","Open your knees out to the sides.","Slowly bring them back together."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-knee-hug","name":"Seated knee hug","category":"chair","group":"Sandalyede Egzersiz","sets":"15 seconds each leg","icon":"🪑","steps":["Lift one knee toward your chest.","Hug it with both arms.","Keep your back straight, breathe, and switch legs.","⚠ If your knee hurts, hold under the knee, not over it."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-hamstring-stretch","name":"Seated hamstring stretch","category":"chair","group":"Sandalyede Egzersiz","sets":"20 seconds each leg","icon":"🪑","steps":["Move to the edge of the chair.","Stretch one leg straight out in front, heel on the floor and toes up.","Keep your back straight and lean forward from your hips.","⚠ Don't round your back or force the stretch."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-figure-four","name":"Seated figure-4 stretch","category":"chair","group":"Sandalyede Egzersiz","sets":"20 seconds each side","icon":"🪑","steps":["Rest one ankle on the opposite knee.","Keep your back straight and lean forward a little.","Feel the stretch in your buttock. Switch sides.","⚠ If your knee hurts, lower your leg and skip this one."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-leg-out-side","name":"Seated side leg tap","category":"chair","group":"Sandalyede Egzersiz","sets":"10 each side","icon":"🪑","steps":["Sit up tall.","Move one leg out to the side and tap the floor.","Bring it back and switch sides."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-knee-drive-twist","name":"Seated cross knee to elbow","category":"chair","group":"Sandalyede Egzersiz","sets":"10 each side","icon":"🪑","steps":["Hands behind your head, elbows wide.","Lift one knee and turn the opposite elbow toward it.","Come back and switch sides.","⚠ Keep the movement small and comfortable. Don't pull on your neck."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-jacks","name":"Seated jumping jacks","category":"chair","group":"Sandalyede Egzersiz","sets":"30 seconds","icon":"🪑","steps":["Sit on the edge of the chair.","Open your legs out to the sides and raise your arms up.","Bring them back together, to the beat."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-leg-pedal","name":"Seated pedaling","category":"chair","group":"Sandalyede Egzersiz","sets":"20 seconds","icon":"🪑","steps":["Hold the sides of the chair.","Pedal your legs like you're riding a bike, with small movements.","Keep your back against the backrest."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-twist","name":"Seated twist","category":"chair","group":"Sandalyede Egzersiz","sets":"15 seconds each side","icon":"🪑","steps":["Cross your arms over your chest, feet flat on the floor.","Turn your upper body to the side and look behind you.","Keep your knees facing forward. Switch sides.","⚠ Turn slowly, and only as far as feels good."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-side-bend","name":"Seated side bend","category":"chair","group":"Sandalyede Egzersiz","sets":"15 seconds each side","icon":"🪑","steps":["Sit up tall.","Raise one arm over your head and lean to the other side.","Keep your bottom on the chair. Switch sides."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-forward-fold","name":"Seated forward fold","category":"chair","group":"Sandalyede Egzersiz","sets":"20 seconds","icon":"🪑","steps":["Legs slightly apart.","Slowly bend forward and let your hands drop toward the floor.","Breathe, then roll up slowly, one vertebra at a time.","⚠ If you have back pain, only go down as far as your knees."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-cat-cow","name":"Seated cat-cow","category":"chair","group":"Sandalyede Egzersiz","sets":"8 times","icon":"🪑","steps":["Hands on your knees.","Cow: arch your back, push your chest out, and look up a little.","Cat: round your back and drop your chin."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-hip-hinge","name":"Seated hip hinge","category":"chair","group":"Sandalyede Egzersiz","sets":"10 times","icon":"🪑","steps":["Cross your arms over your chest.","Lean forward from your hips with a straight back.","Come back to sitting up tall."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-back-extension","name":"Seated back extension","category":"chair","group":"Sandalyede Egzersiz","sets":"8 times","icon":"🪑","steps":["Hands behind your head, elbows wide.","Lift your chest and look up a little.","Come back slowly.","⚠ Keep it small. Don't force an arch in your lower back."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-torso-circles","name":"Seated torso circles","category":"chair","group":"Sandalyede Egzersiz","sets":"5 each direction","icon":"🪑","steps":["Hands on your knees.","Draw a big circle with your upper body.","Go slowly, then switch direction."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-windmill","name":"Seated windmill","category":"chair","group":"Sandalyede Egzersiz","sets":"8 each side","icon":"🪑","steps":["Legs apart, arms out to the sides.","Bend down and reach one hand toward the opposite foot.","Come back up and switch sides.","⚠ Only go down as far as feels good for your back."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-lean-back-hold","name":"Seated lean back","category":"chair","group":"Sandalyede Egzersiz","sets":"8 times","icon":"🪑","steps":["Sit on the edge of the chair with your arms crossed.","Lean back a little with a straight back and a tight belly.","Hold for 3 seconds and come back.","⚠ Just a little way back. If your back hurts, skip it."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-reach-across","name":"Seated cross reach","category":"chair","group":"Sandalyede Egzersiz","sets":"10 each side","icon":"🪑","steps":["Sit up tall.","Reach one arm across your body, as if grabbing something off a table.","Turn your body a little and come back."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-neck-tilt","name":"Seated neck side tilt","category":"chair","group":"Sandalyede Egzersiz","sets":"5 each side","icon":"🪑","steps":["Sit up tall, shoulders relaxed.","Bring your ear toward your shoulder without lifting the shoulder.","Hold for 3 seconds, come back, and switch sides."],"view":"upper","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-neck-turn","name":"Seated neck rotation","category":"chair","group":"Sandalyede Egzersiz","sets":"5 each side","icon":"🪑","steps":["Keep your chin level with the floor.","Slowly turn your head to look over your shoulder.","Come back and turn to the other side."],"view":"upper","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-chin-tuck","name":"Seated chin tuck","category":"chair","group":"Sandalyede Egzersiz","sets":"10 times","icon":"🪑","steps":["Look straight ahead, back against the backrest.","Pull your head straight back, like making a double chin.","Hold for 2 seconds and release. Good for screen time."],"view":"upper","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-neck-nod","name":"Seated neck nod","category":"chair","group":"Sandalyede Egzersiz","sets":"8 times","icon":"🪑","steps":["Slowly lower your chin to your chest.","Look up a little.","Don't throw your head back."],"view":"upper","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-shoulder-shrugs","name":"Seated shoulder shrugs","category":"chair","group":"Sandalyede Egzersiz","sets":"10 times","icon":"🪑","steps":["Arms relaxed at your sides.","Lift your shoulders up to your ears.","Hold for a second and let them drop."],"view":"upper","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-shoulder-rolls","name":"Seated shoulder rolls","category":"chair","group":"Sandalyede Egzersiz","sets":"10 times","icon":"🪑","steps":["Lift your shoulders up to your ears.","Roll them back and squeeze your shoulder blades together.","Lower them down. Make a big, slow circle."],"view":"upper","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-scapular-squeeze","name":"Seated scapular squeeze","category":"chair","group":"Sandalyede Egzersiz","sets":"10 times","icon":"🪑","steps":["Elbows bent, close to your body.","Squeeze your shoulder blades together and push your chest out.","Hold for 3 seconds and release."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-w-squeeze","name":"Seated W squeeze","category":"chair","group":"Sandalyede Egzersiz","sets":"10 times","icon":"🪑","steps":["Elbows at shoulder height, forearms pointing up.","Pull your elbows down and back, like a W.","Squeeze your shoulder blades and hold for a second."],"view":"upper","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-chest-opener","name":"Seated chest opener","category":"chair","group":"Sandalyede Egzersiz","sets":"20 seconds","icon":"🪑","steps":["Sit on the edge of the chair.","Clasp your hands behind your back.","Push your chest out and pull your hands a little back and down."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-upper-back-stretch","name":"Seated upper back stretch","category":"chair","group":"Sandalyede Egzersiz","sets":"20 seconds","icon":"🪑","steps":["Hug yourself, hands on your shoulders.","Round your upper back and drop your chin.","Feel the stretch between your shoulder blades."],"view":"upper","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-cross-body-stretch","name":"Seated cross-body stretch","category":"chair","group":"Sandalyede Egzersiz","sets":"20 seconds each side","icon":"🪑","steps":["Bring one straight arm across your chest.","Use your other hand to pull it closer, just above the elbow.","Keep your shoulders down. Switch sides."],"view":"upper","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-punches","name":"Seated punches","category":"chair","group":"Sandalyede Egzersiz","sets":"30 seconds","icon":"🪑","steps":["Sit up tall with your fists by your chin.","Punch one arm forward and pull it back, alternating arms.","Turn your body a little with each punch."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-overhead-punches","name":"Seated overhead punches","category":"chair","group":"Sandalyede Egzersiz","sets":"30 seconds","icon":"🪑","steps":["Fists by your shoulders.","Push one arm up and bring it back.","Alternate arms, to the beat."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-arm-circles","name":"Seated arm circles","category":"chair","group":"Sandalyede Egzersiz","sets":"15 seconds each direction","icon":"🪑","steps":["Stretch your arms out to the sides at shoulder height.","Draw small circles in the air.","After 15 seconds, switch direction."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-overhead-reach","name":"Seated overhead reach","category":"chair","group":"Sandalyede Egzersiz","sets":"10 each side","icon":"🪑","steps":["Sit up tall.","Reach one arm high toward the ceiling.","Lower it and switch arms."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-biceps-curl","name":"Seated elbow curls","category":"chair","group":"Sandalyede Egzersiz","sets":"12 times","icon":"🪑","steps":["Arms at your sides.","Bend your elbows and bring your fists up to your shoulders.","Lower slowly."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-shoulder-press","name":"Seated shoulder press","category":"chair","group":"Sandalyede Egzersiz","sets":"10 times","icon":"🪑","steps":["Arms in a W shape, forearms pointing up.","Push your arms up until they are almost straight.","Slowly come back to the W."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-front-raise","name":"Seated front raise","category":"chair","group":"Sandalyede Egzersiz","sets":"10 times","icon":"🪑","steps":["Arms straight down.","Raise them in front of you to shoulder height.","Lower slowly."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-lateral-raise","name":"Seated lateral raise","category":"chair","group":"Sandalyede Egzersiz","sets":"10 times","icon":"🪑","steps":["Arms straight at your sides.","Raise them out to the sides to shoulder height.","Lower slowly."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-rowing","name":"Seated rowing","category":"chair","group":"Sandalyede Egzersiz","sets":"12 times","icon":"🪑","steps":["Reach your arms forward.","Pull your elbows back, like rowing.","Squeeze your shoulder blades and come back."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-wrist-circles","name":"Seated wrist circles","category":"chair","group":"Sandalyede Egzersiz","sets":"10 each direction","icon":"🪑","steps":["Elbows bent, forearms forward.","Turn your hands in circles.","After 10, switch direction."],"view":"upper","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-wrist-stretch","name":"Seated wrist flexor stretch","category":"chair","group":"Sandalyede Egzersiz","sets":"20 seconds each hand","icon":"🪑","steps":["Stretch one arm straight out in front, palm facing away from you.","Use your other hand to gently pull your fingers toward you.","Switch hands. Great after working with a mouse.","⚠ Gentle stretch only, no pain."],"view":"upper","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-hands-to-shoulders","name":"Seated hands to shoulders","category":"chair","group":"Sandalyede Egzersiz","sets":"10 times","icon":"🪑","steps":["Fingertips on your shoulders.","Reach your arms straight up.","Bring them back to your shoulders and lower."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-breathing-arms","name":"Seated breathing with arms","category":"chair","group":"Sandalyede Egzersiz","sets":"5 breaths","icon":"🪑","steps":["Breathe in and raise your arms out to the sides and up.","Breathe out and lower them slowly.","Keep a slow, easy pace."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-reach-up-stretch","name":"Seated full stretch","category":"chair","group":"Sandalyede Egzersiz","sets":"3 times","icon":"🪑","steps":["Lace your fingers and raise your arms over your head.","Stretch up as if touching the ceiling.","Hold for 5 seconds and let go."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-knee-lift-arms-up","name":"Seated knee lift with arm pull","category":"chair","group":"Sandalyede Egzersiz","sets":"10 each side","icon":"🪑","steps":["Arms up over your head.","Lift one knee and pull your arms down toward it.","Come back and switch legs."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-star-reach","name":"Seated diagonal star reach","category":"chair","group":"Sandalyede Egzersiz","sets":"8 each side","icon":"🪑","steps":["Sit up tall.","Reach one arm diagonally up and the opposite leg out to the side.","Come back and switch sides."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"pelvic-tilt-lying","name":"Lying pelvic tilt","category":"floor-lying","group":"Yerde Uzanarak","sets":"10 reps","icon":"🛏","steps":["Lie on your back with your knees bent and your feet flat on the floor.","Press your lower back into the floor and tilt your pelvis up a little.","Release slowly. Keep the movement small."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"glute-bridge","name":"Glute bridge","category":"floor-lying","group":"Yerde Uzanarak","sets":"10 reps","icon":"🛏","steps":["Lie on your back with your knees bent and your hands on the floor.","Push through your heels and lift your hips until your body makes a straight line from your shoulders to your knees.","Hold for 2 seconds and lower slowly.","⚠ Don't arch your back. Lower back pain? Lift less."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"knee-to-chest-single","name":"Single knee to chest","category":"floor-lying","group":"Yerde Uzanarak","sets":"20 seconds each leg","icon":"🛏","steps":["Lie on your back with your knees bent.","Hug one knee and pull it toward your chest.","Keep your head and shoulders on the floor. Switch legs."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"knees-to-chest-hug","name":"Double knee hug","category":"floor-lying","group":"Yerde Uzanarak","sets":"30 seconds","icon":"🛏","steps":["Lie on your back and lift both knees.","Hug them and pull them toward your chest.","Rock gently from side to side and breathe."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"supine-twist","name":"Supine knee drop twist","category":"floor-lying","group":"Yerde Uzanarak","sets":"20 seconds each side","icon":"🛏","steps":["Lie on your back with your arms out to the sides and your knees bent.","Slowly let both knees drop to one side.","Keep your shoulders on the floor. Come back and switch sides.","⚠ Back pain? Lower your knees only halfway."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"knee-sways","name":"Knee windshield wipers","category":"floor-lying","group":"Yerde Uzanarak","sets":"10 each side","icon":"🛏","steps":["Lie on your back with your feet flat on the floor.","Tip your knees together a little to one side and back.","Keep it small and soft, like a car's windshield wiper."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"dead-bug","name":"Dead bug","category":"floor-lying","group":"Yerde Uzanarak","sets":"8 each side","icon":"🛏","steps":["Lie on your back with your arms up to the ceiling and your knees lifted at a right angle.","Lower one arm overhead and stretch the opposite leg out.","Come back and switch sides. Keep your lower back pressed to the floor.","⚠ Hard on your back? Move only the leg, not the arm."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"lying-arm-reach","name":"Lying overhead arm reach","category":"floor-lying","group":"Yerde Uzanarak","sets":"8 each arm","icon":"🛏","steps":["Lie on your back with your knees bent and your arms up to the ceiling.","Slowly lower one arm overhead.","Bring it back and switch arms. Don't arch your back."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"heel-slides","name":"Heel slides","category":"floor-lying","group":"Yerde Uzanarak","sets":"10 each leg","icon":"🛏","steps":["Lie on your back with your knees bent.","Slide one heel along the floor until your leg is straight.","Slide it back slowly and switch legs."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"straight-leg-raise","name":"Straight leg raise","category":"floor-lying","group":"Yerde Uzanarak","sets":"10 each leg","icon":"🛏","steps":["Lie on your back with one knee bent.","Keep the other leg straight and lift it to the height of your bent knee.","Lower it slowly. After 10, switch legs."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"leg-lowers","name":"Single leg lowers","category":"floor-lying","group":"Yerde Uzanarak","sets":"8 each leg","icon":"🛏","steps":["Lie on your back with one leg bent and your foot on the floor.","Raise the other leg straight up toward the ceiling.","Slowly lower it toward the floor and bring it back up.","⚠ Back lifting off the floor? Don't lower your leg as far."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"supine-marching","name":"Supine marching","category":"floor-lying","group":"Yerde Uzanarak","sets":"10 each leg","icon":"🛏","steps":["Lie on your back with your knees bent.","Lift one foot until your knee is over your hip, keeping the same bend.","Lower it quietly and switch legs."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"toe-taps","name":"Toe taps","category":"floor-lying","group":"Yerde Uzanarak","sets":"8 each leg","icon":"🛏","steps":["Lie on your back with both knees lifted at a right angle.","Lower one leg and tap your toes on the floor.","Bring it back and switch legs. Keep your lower back pressed to the floor."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"slow-bicycle-legs","name":"Slow bicycle legs","category":"floor-lying","group":"Yerde Uzanarak","sets":"10 each leg","icon":"🛏","steps":["Lie on your back with your knees lifted.","Straighten one leg out in the air as the other knee comes toward your chest.","Switch slowly, like pedaling a bike. Keep your head on the floor."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"lying-hamstring-stretch","name":"Lying hamstring stretch","category":"floor-lying","group":"Yerde Uzanarak","sets":"30 seconds each leg","icon":"🛏","steps":["Lie on your back with your knees bent.","Lift one leg straight and hold it behind your thigh.","Pull gently until you feel a pleasant stretch. Switch legs."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"figure-four-stretch","name":"Figure-four stretch","category":"floor-lying","group":"Yerde Uzanarak","sets":"30 seconds each side","icon":"🛏","steps":["Lie on your back with your knees bent.","Rest your left ankle on your right knee.","Lift your right leg and pull it toward your chest. Switch sides."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"lying-snow-angel","name":"Lying snow angel","category":"floor-lying","group":"Yerde Uzanarak","sets":"8 reps","icon":"🛏","steps":["Lie on your back with your arms flat on the floor.","Slide your arms along the floor until they are overhead.","Bring them back down to your sides. Go slowly, with no shoulder pain."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"lying-full-stretch","name":"Lying full-body stretch","category":"floor-lying","group":"Yerde Uzanarak","sets":"5 reps","icon":"🛏","steps":["Lie on your back with your legs straight.","Reach your arms overhead and point your toes.","Stretch out as long as you can, breathe, and let go."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"lying-ankle-pumps","name":"Ankle pumps","category":"floor-lying","group":"Yerde Uzanarak","sets":"20 reps","icon":"🛏","steps":["Lie on your back with your legs straight.","Pull your toes toward you, then point them away.","Good for blood flow."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"gentle-curl-up","name":"Gentle curl-up","category":"floor-lying","group":"Yerde Uzanarak","sets":"8 reps","icon":"🛏","steps":["Lie on your back with your knees bent.","Tuck your chin and lift your head and shoulders a little, reaching your hands toward your knees.","Lower slowly.","⚠ Don't pull on your neck. Neck pain? Keep your head on the floor."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"happy-baby","name":"Happy baby","category":"floor-lying","group":"Yerde Uzanarak","sets":"30 seconds","icon":"🛏","steps":["Lie on your back and bring your knees up toward your armpits.","Hold your shins or the outside of your feet.","Rock a little from side to side."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"clam-shell","name":"Clam shell","category":"floor-lying","group":"Yerde Uzanarak","sets":"12 each side","icon":"🛏","steps":["Lie on your side with your knees bent and your head on your arm.","Keep your feet together. Open your top knee like a clam shell.","Close it slowly. Don't let your hips roll back."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"side-lying-leg-lift","name":"Side-lying leg lift","category":"floor-lying","group":"Yerde Uzanarak","sets":"12 each side","icon":"🛏","steps":["Lie on your side with your bottom leg bent.","Keep your top leg straight and slowly lift it.","Lower it with control. Keep your toes pointing forward."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"side-lying-inner-thigh","name":"Side-lying inner thigh lift","category":"floor-lying","group":"Yerde Uzanarak","sets":"12 each side","icon":"🛏","steps":["Lie on your side. Bend your top leg and rest it in front of you.","Keep your bottom leg straight and lift it a little off the floor.","Lower it slowly."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"side-leg-swing","name":"Side-lying leg swing","category":"floor-lying","group":"Yerde Uzanarak","sets":"10 each side","icon":"🛏","steps":["Lie on your side with your bottom leg bent.","Swing your top leg forward and back, low to the floor.","Keep your body still. Only your leg moves."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"open-book","name":"Open book","category":"floor-lying","group":"Yerde Uzanarak","sets":"8 each side","icon":"🛏","steps":["Lie on your side with your knees bent in front of you and your arms straight out in front.","Open your top arm over to the other side and follow it with your eyes.","Keep your knees together. Come back slowly."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"side-lying-quad-stretch","name":"Side-lying quad stretch","category":"floor-lying","group":"Yerde Uzanarak","sets":"30 seconds each side","icon":"🛏","steps":["Lie on your side with your head on your arm.","Hold your top foot and bring your heel toward your seat.","Keep your knees close together. Switch sides.","⚠ Knee pain? Hold your pants or a towel instead of your foot."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"prone-superman","name":"Gentle superman","category":"floor-lying","group":"Yerde Uzanarak","sets":"8 reps","icon":"🛏","steps":["Lie on your stomach with your arms straight out in front.","Lift your arms, chest, and legs a little off the floor.","Hold for 2 seconds and lower. Look down at the floor.","⚠ Don't strain to lift high. Lower back pain? Lift only your arms."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"prone-opposite-lift","name":"Prone opposite arm and leg lift","category":"floor-lying","group":"Yerde Uzanarak","sets":"8 each side","icon":"🛏","steps":["Lie on your stomach with your arms out in front.","Lift one arm and the opposite leg a little.","Lower them and switch sides."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"prone-swimmers","name":"Prone swimmers","category":"floor-lying","group":"Yerde Uzanarak","sets":"20 seconds","icon":"🛏","steps":["Lie on your stomach with your arms out in front and your chest lifted a little.","Flutter opposite arms and legs up and down, taking turns.","Make small, quick moves, like swimming."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"prone-y-raise","name":"Prone Y raise","category":"floor-lying","group":"Yerde Uzanarak","sets":"10 reps","icon":"🛏","steps":["Lie on your stomach with your arms out at an angle, like the letter Y.","Lift your arms a little, thumbs up.","Squeeze your shoulder blades together, hold, and lower."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"prone-w-squeeze","name":"Prone W squeeze","category":"floor-lying","group":"Yerde Uzanarak","sets":"10 reps","icon":"🛏","steps":["Lie on your stomach with your elbows bent out to the sides, like a W.","Lift your elbows and hands a little and squeeze your shoulder blades together.","Hold for 2 seconds and lower."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"sphinx","name":"Sphinx","category":"floor-lying","group":"Yerde Uzanarak","sets":"30 seconds","icon":"🛏","steps":["Lie on your stomach and rest your forearms on the floor, elbows under your shoulders.","Lift your chest and look forward.","Keep your stomach and hips on the floor and your shoulders away from your ears.","⚠ Feel pressure in your lower back? Move your elbows farther forward."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"gentle-cobra","name":"Gentle cobra","category":"floor-lying","group":"Yerde Uzanarak","sets":"6 reps","icon":"🛏","steps":["Lie on your stomach with your hands next to your chest and your elbows close to your body.","Press lightly and lift your chest, keeping your elbows bent.","Lower slowly.","⚠ Go only as high as feels comfortable. Back pain? Stick with the sphinx."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"prone-leg-lift","name":"Prone leg lift","category":"floor-lying","group":"Yerde Uzanarak","sets":"10 each leg","icon":"🛏","steps":["Lie on your stomach with your arms by your sides.","Lift one straight leg a little off the floor.","Lower it and switch legs. Keep your hips on the floor."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"prone-heel-to-seat","name":"Prone knee bend","category":"floor-lying","group":"Yerde Uzanarak","sets":"10 each leg","icon":"🛏","steps":["Lie on your stomach with your arms by your sides.","Bend one knee and bring your heel toward your seat.","Lower it slowly and switch legs."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"cat-cow","name":"Cat-cow on all fours","category":"floor-lying","group":"Yerde Uzanarak","sets":"8 reps","icon":"🛏","steps":["Get on all fours, hands under your shoulders and knees under your hips.","Round your back up like a cat and look toward your belly.","Let your belly drop and look up, like a cow.","⚠ Sensitive knees? Put a pillow or a folded blanket under them."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"bird-dog","name":"Bird-dog","category":"floor-lying","group":"Yerde Uzanarak","sets":"8 each side","icon":"🛏","steps":["Get on all fours with your back straight.","Reach one arm forward and the opposite leg back.","Hold for 2 seconds, come back, and switch sides.","⚠ Sensitive knees? Put a pillow or a folded blanket under them."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"bird-dog-easy","name":"Easy bird-dog","category":"floor-lying","group":"Yerde Uzanarak","sets":"6 each arm and leg","icon":"🛏","steps":["Get on all fours with your back straight.","Reach one arm forward, then bring it back.","Slide one leg straight back, then bring it back. No rush.","⚠ Sensitive knees? Put a pillow or a folded blanket under them."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"thread-the-needle","name":"Thread the needle","category":"floor-lying","group":"Yerde Uzanarak","sets":"20 seconds each side","icon":"🛏","steps":["Get on all fours.","Slide one arm under your body to the other side, letting your shoulder drop toward the floor.","Breathe, come back, and switch sides.","⚠ Sensitive knees? Put a pillow or a folded blanket under them."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"child-pose","name":"Child's pose","category":"floor-lying","group":"Yerde Uzanarak","sets":"30 seconds","icon":"🛏","steps":["Kneel on the floor and sit back on your heels.","Lower your chest to your thighs and stretch your arms forward on the floor.","Rest your forehead on the floor and breathe into your back.","⚠ Knee pain? Put a pillow between your seat and your heels."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"fours-rock-back","name":"Quadruped rock back","category":"floor-lying","group":"Yerde Uzanarak","sets":"10 reps","icon":"🛏","steps":["Get on all fours.","Shift your seat back toward your heels, keeping your hands in place.","Come back forward. Keep your back long.","⚠ Sensitive knees? Put a pillow or a folded blanket under them."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"fire-hydrant","name":"Fire hydrant","category":"floor-lying","group":"Yerde Uzanarak","sets":"10 each side","icon":"🛏","steps":["Get on all fours.","Lift one knee out to the side, keeping it bent.","Lower it slowly. Don't let your hips tilt.","⚠ Sensitive knees? Put a pillow or a folded blanket under them."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"donkey-kick","name":"Donkey kick","category":"floor-lying","group":"Yerde Uzanarak","sets":"10 each leg","icon":"🛏","steps":["Get on all fours.","Push one heel up toward the ceiling, keeping your knee bent.","Lower it slowly. Don't arch your back.","⚠ Sensitive knees? Put a pillow or a folded blanket under them."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"fours-tail-wag","name":"Tail wag","category":"floor-lying","group":"Yerde Uzanarak","sets":"10 each side","icon":"🛏","steps":["Get on all fours.","Turn your head and your seat toward the same side, like a dog wagging its tail.","Switch to the other side. Keep it soft.","⚠ Sensitive knees? Put a pillow or a folded blanket under them."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"knee-plank","name":"Knee plank","category":"floor-lying","group":"Yerde Uzanarak","sets":"20 seconds","icon":"🛏","steps":["Rest on your forearms with your elbows under your shoulders.","Keep your knees on the floor and your body in a straight line from your head to your knees.","Tighten your belly and breathe.","⚠ Lower back pain? Lower your hips or stop."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-butterfly-stretch","name":"Butterfly stretch","category":"floor-seated","group":"Yerde Oturarak","sets":"30 seconds","icon":"🧎","steps":["Sit and press the soles of your feet together.","Let your knees drop out to the sides and hold your feet with your hands.","Sit tall and breathe. Don't push down on your knees."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-butterfly-knee-flaps","name":"Butterfly knee flaps","category":"floor-seated","group":"Yerde Oturarak","sets":"20 reps","icon":"🧎","steps":["Sit in butterfly pose with the soles of your feet together.","Gently lift and lower your knees, like wings.","Keep the movement small and soft, no bouncing."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-butterfly-forward-lean","name":"Butterfly forward lean","category":"floor-seated","group":"Yerde Oturarak","sets":"20 seconds","icon":"🧎","steps":["Sit in butterfly pose with your hands on your feet.","Lean forward with a straight back, bringing your chest toward your feet.","⚠ If your lower back pulls, lean only a little."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-long-sit-forward-fold","name":"Seated forward fold","category":"floor-seated","group":"Yerde Oturarak","sets":"20 seconds","icon":"🧎","steps":["Sit with your legs straight out in front of you.","Reach your hands toward your feet and lean forward from your hips.","⚠ If your back or knees pull, bend your knees a little."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-soft-knee-forward-fold","name":"Soft-knee forward fold","category":"floor-seated","group":"Yerde Oturarak","sets":"20 seconds","icon":"🧎","steps":["Legs out in front, knees slightly bent.","Rest your hands on your shins and lean forward.","An easier version for your back and the backs of your thighs."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-head-to-knee-easy","name":"Easy head-to-knee stretch","category":"floor-seated","group":"Yerde Oturarak","sets":"20 seconds each side","icon":"🧎","steps":["Keep one leg straight and place the other foot by your inner thigh.","Turn toward the straight leg and lean forward.","Switch sides."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-flexed-foot-hamstring","name":"Seated hamstring with flexed foot","category":"floor-seated","group":"Yerde Oturarak","sets":"20 seconds each leg","icon":"🧎","steps":["Keep one leg straight. Bend the other with the foot flat on the floor.","Pull the toes of your straight leg toward you.","Lean forward a little with a straight back. Switch legs."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-straddle-side-reach","name":"Straddle side reach","category":"floor-seated","group":"Yerde Oturarak","sets":"15 seconds each side","icon":"🧎","steps":["Open your straight legs out to the sides, as wide as feels good.","Raise one arm over your head and lean toward the opposite leg.","Feel the stretch along the side of your body. Switch sides."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-straddle-forward-lean","name":"Straddle forward lean","category":"floor-seated","group":"Yerde Oturarak","sets":"20 seconds","icon":"🧎","steps":["Open your legs out to the sides, knees pointing up to the ceiling.","Place your hands in front of you and walk them forward.","⚠ Don't force it. If your back hurts, stay more upright."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-straddle-reach-to-foot","name":"Straddle reach to foot","category":"floor-seated","group":"Yerde Oturarak","sets":"6 each side","icon":"🧎","steps":["Open your legs wide, arms out to the sides.","Twist and reach one hand toward the opposite foot.","Come back to center and switch to the other side."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-straddle-twist","name":"Straddle twist","category":"floor-seated","group":"Yerde Oturarak","sets":"8 each side","icon":"🧎","steps":["Open your legs wide, arms out at shoulder height.","Turn your upper body to one side. Keep your hips still.","Come back and turn to the other side."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-cross-legged-twist","name":"Cross-legged twist","category":"floor-seated","group":"Yerde Oturarak","sets":"20 seconds each side","icon":"🧎","steps":["Sit cross-legged with your back tall.","Place one hand on the opposite knee and the other hand on the floor behind you.","Twist slowly and look over your shoulder. Switch sides."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-cross-legged-side-bend","name":"Cross-legged side bend","category":"floor-seated","group":"Yerde Oturarak","sets":"15 seconds each side","icon":"🧎","steps":["Sit cross-legged with one hand on the floor beside you.","Sweep the other arm up over your head.","Lean to the side and breathe. Switch sides."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-cross-legged-forward-walk","name":"Cross-legged forward walk","category":"floor-seated","group":"Yerde Oturarak","sets":"20 seconds","icon":"🧎","steps":["Sit cross-legged.","Walk your hands forward on the floor and let your body follow.","Breathe while you lean forward, then slowly come back up."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-cross-legged-arm-breath","name":"Cross-legged arm raise breathing","category":"floor-seated","group":"Yerde Oturarak","sets":"6 breaths","icon":"🧎","steps":["Sit cross-legged with your back tall.","As you breathe in, raise your arms out to the sides and over your head.","As you breathe out, lower them slowly."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-cross-legged-torso-circles","name":"Cross-legged torso circles","category":"floor-seated","group":"Yerde Oturarak","sets":"5 each direction","icon":"🧎","steps":["Sit cross-legged with your hands on your knees.","Draw a big circle with your chest: forward, to the side, back, to the other side.","After 5, switch direction."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-cross-legged-cat-cow","name":"Seated cat-cow","category":"floor-seated","group":"Yerde Oturarak","sets":"8 reps","icon":"🧎","steps":["Sit cross-legged with your hands on your knees.","Round your back and drop your chin, like a cat.","Open your chest forward and look up slightly."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-cross-legged-knee-folds","name":"Cross-legged fold over each knee","category":"floor-seated","group":"Yerde Oturarak","sets":"15 seconds each side","icon":"🧎","steps":["Sit cross-legged.","Turn your body slightly toward one knee and lean over it.","Place your hands on the floor near that knee. Switch sides."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-staff-pose","name":"Staff pose","category":"floor-seated","group":"Yerde Oturarak","sets":"30 seconds","icon":"🧎","steps":["Legs straight out in front, toes pointing up to the ceiling.","Place your hands on the floor by your hips and press down lightly.","Lengthen your back and draw your shoulders down."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-gentle-v-sit","name":"Gentle V-sit","category":"floor-seated","group":"Yerde Oturarak","sets":"5 reps","icon":"🧎","steps":["Sit with your knees bent and hold the backs of your knees.","Lean back a little and lift your feet off the floor.","⚠ Keep your back straight. If your lower back hurts, keep your feet on the floor."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-easy-boat-hold","name":"Easy boat pose","category":"floor-seated","group":"Yerde Oturarak","sets":"15 seconds","icon":"🧎","steps":["Lean back with your shins parallel to the floor.","Reach your arms straight forward beside your knees.","⚠ Pull your belly in. Back hurts? Hold your thighs with your hands."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-boat-one-leg-reach","name":"Boat with one-leg reach","category":"floor-seated","group":"Yerde Oturarak","sets":"6 each leg","icon":"🧎","steps":["In easy boat pose, hold your thighs with your hands.","Straighten one leg out at an angle, then bring it back.","⚠ Only if your back feels good. Switch legs."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-lean-back-leg-lift","name":"Lean-back straight leg lift","category":"floor-seated","group":"Yerde Oturarak","sets":"8 each leg","icon":"🧎","steps":["Lean back on your hands with one knee bent.","Lift the straight leg up to the height of your other knee.","⚠ Lower it slowly. Wrists hurt? Lean on your elbows."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-lean-back-scissors","name":"Lean-back scissors","category":"floor-seated","group":"Yerde Oturarak","sets":"20 reps","icon":"🧎","steps":["Lean back on your hands with your legs straight, just above the floor.","Lift one leg as you lower the other, switching back and forth.","⚠ Pull your belly in. Back hurts? Keep one foot on the floor."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-lean-back-open-close-scissors","name":"Lean-back open-close scissors","category":"floor-seated","group":"Yerde Oturarak","sets":"16 reps","icon":"🧎","steps":["Lean back on your hands with your legs slightly raised.","Open your legs out to the sides, then close them so they cross.","⚠ If your back pulls, do it with your feet on the floor."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-lean-back-marching","name":"Seated marching","category":"floor-seated","group":"Yerde Oturarak","sets":"20 steps","icon":"🧎","steps":["Lean back on your hands with your knees bent.","Lift one knee toward your chest and lower it, then the other.","⚠ Don't hunch your shoulders. You can lean on your elbows."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-knee-windshield-wipers","name":"Seated knee windshield wipers","category":"floor-seated","group":"Yerde Oturarak","sets":"8 each side","icon":"🧎","steps":["Lean back on your hands, knees bent and feet wide apart.","Let both knees fall to one side.","Bring them up and let them fall to the other side."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-seated-figure-four","name":"Seated figure-four stretch","category":"floor-seated","group":"Yerde Oturarak","sets":"20 seconds each side","icon":"🧎","steps":["Lean back on your hands with your knees bent.","Place one ankle on the opposite knee.","Bring your chest a little forward. Switch sides."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-ankle-pumps","name":"Seated ankle pumps","category":"floor-seated","group":"Yerde Oturarak","sets":"20 reps","icon":"🧎","steps":["Sit with your legs straight.","Point your feet forward, like a ballerina.","Pull your toes back toward you."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-ankle-circles","name":"Seated ankle circles","category":"floor-seated","group":"Yerde Oturarak","sets":"10 each direction","icon":"🧎","steps":["Legs straight out in front.","Draw big circles with your feet.","Only your ankles move. After 10, switch direction."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-alternate-toe-point-flex","name":"Alternating toe point and flex","category":"floor-seated","group":"Yerde Oturarak","sets":"20 reps","icon":"🧎","steps":["Legs straight out in front.","Point the toes of one foot forward as you pull the other foot back.","Switch at a comfortable pace."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-leg-roll-in-out","name":"Seated leg rolls","category":"floor-seated","group":"Yerde Oturarak","sets":"15 reps","icon":"🧎","steps":["Legs straight out in front, hands on the floor behind you.","Roll your legs so your toes point out.","Then roll them in until your big toes touch."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-heel-slides","name":"Seated heel slides","category":"floor-seated","group":"Yerde Oturarak","sets":"10 each leg","icon":"🧎","steps":["Legs straight, hands on the floor behind you.","Slide one heel toward your bottom, then straighten it back out.","⚠ Move gently, only as far as your knee feels good. Switch legs."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-knee-hug-to-chest","name":"Seated knee hug","category":"floor-seated","group":"Yerde Oturarak","sets":"15 seconds each leg","icon":"🧎","steps":["Legs straight out in front.","Bring one knee toward your chest and hug it with both arms.","Keep your back tall. Switch legs."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-knees-to-chest-rock-back","name":"Rock back on the spine","category":"floor-seated","group":"Yerde Oturarak","sets":"8 reps","icon":"🧎","steps":["Sit and hug your knees, back rounded and chin tucked to your chest.","Roll back onto your shoulder blades, then roll up to sitting.","⚠ Only on a soft surface. Don't roll onto your neck."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-hug-knees-side-sway","name":"Hug-knees side sway","category":"floor-seated","group":"Yerde Oturarak","sets":"10 reps","icon":"🧎","steps":["Sit and hug your knees.","Slowly rock to one side and then the other.","Feels nice on your lower back. Breathe calmly."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-bent-knee-spinal-twist","name":"Seated spinal twist, knee bent","category":"floor-seated","group":"Yerde Oturarak","sets":"20 seconds each side","icon":"🧎","steps":["Keep one leg straight. Bend the other and place that foot on the outside of the straight knee.","Twist toward the bent knee and rest your opposite elbow against its outside.","Place your other hand on the floor behind you. Switch sides."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-long-sit-side-bend","name":"Long-sit side bend","category":"floor-seated","group":"Yerde Oturarak","sets":"6 each side","icon":"🧎","steps":["Legs straight out in front, one hand on the floor by your hip.","Raise your other arm over your head.","Slowly lean to the side, come back, and switch."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-butterfly-twist","name":"Butterfly twist","category":"floor-seated","group":"Yerde Oturarak","sets":"15 seconds each side","icon":"🧎","steps":["Sit in butterfly pose with your back tall.","Place one hand on the opposite knee and the other on the floor behind you.","Twist gently, then switch sides."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"floor-seated-chest-opener","name":"Seated chest opener","category":"floor-seated","group":"Yerde Oturarak","sets":"20 seconds","icon":"🧎","steps":["Sit with your knees bent, hands on the floor behind you.","Squeeze your shoulder blades together and lift your chest.","⚠ Wrists hurt? Turn your fingers out to the sides."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"small-leg-circles","name":"Small leg circles","category":"hips","group":"Kalça & Bacak","sets":"8 each direction","icon":"🦵","steps":["Hold the back of a chair and stand on one leg.","Keep the other leg straight and a little forward, and draw small circles in the air with it.","Switch direction, then switch legs."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"side-leg-raise","name":"Standing side leg raise","category":"hips","group":"Kalça & Bacak","sets":"10 each leg","icon":"🦵","steps":["Hold the back of a chair with one hand.","Lift one straight leg out to the side, toes pointing forward.","Lower it slowly. Keep your body upright."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"knee-lift-march","name":"Marching in place","category":"hips","group":"Kalça & Bacak","sets":"30 seconds","icon":"🦵","steps":["March in place, lifting your knees.","Swing your arms in opposition to your legs.","Go at a comfortable pace and land softly on your whole foot."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"standing-hamstring-curl","name":"Standing hamstring curl","category":"hips","group":"Kalça & Bacak","sets":"10 each leg","icon":"🦵","steps":["Hold the back of a chair with both hands.","Bend one knee and bring your heel toward your butt.","Keep your thighs side by side. Lower slowly."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"heel-kicks","name":"Gentle butt kicks","category":"hips","group":"Kalça & Bacak","sets":"30 seconds","icon":"🦵","steps":["March in place and kick each heel back toward your butt.","Hands on your hips, or let them swing.","Keep an easy pace and land softly."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"forward-toe-taps","name":"Forward toe taps","category":"hips","group":"Kalça & Bacak","sets":"10 each leg","icon":"🦵","steps":["Hands on your hips.","Reach one foot forward and tap your toes on the floor.","Bring it back and switch legs."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"back-toe-taps","name":"Reverse toe taps","category":"hips","group":"Kalça & Bacak","sets":"10 each leg","icon":"🦵","steps":["Hands on your hips.","Reach one foot back and tap your toes on the floor.","Stand tall. Bring it back and switch legs."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"side-step-taps","name":"Side step taps","category":"hips","group":"Kalça & Bacak","sets":"10 each side","icon":"🦵","steps":["Take a small step to the side and tap your toes.","Come back to center and repeat on the other side.","Open your arms out to the sides with each step."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"sit-back-squat","name":"Sit-back squat","category":"hips","group":"Kalça & Bacak","sets":"8 reps","icon":"🦵","steps":["Push your hips back as if sitting on an imaginary chair.","Lean forward and reach your arms out in front for balance.","⚠ Go down only as far as feels good for your knees, and push up through your heels."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"wide-mini-squat","name":"Wide mini squat","category":"hips","group":"Kalça & Bacak","sets":"10 reps","icon":"🦵","steps":["Stand with your feet wide, toes turned out a little.","Lower yourself a little, letting your knees open toward your toes.","⚠ Keep the dip small and your back straight."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"squat-to-calf-raise","name":"Squat to calf raise","category":"hips","group":"Kalça & Bacak","sets":"8 reps","icon":"🦵","steps":["Lower into a small squat.","Stand up and keep going onto your toes, arms reaching up.","Slowly lower back onto your heels."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"shallow-split-squat","name":"Shallow split squat","category":"hips","group":"Kalça & Bacak","sets":"8 each leg","icon":"🦵","steps":["Stand with one foot a big step in front of the other. Both feet stay in place.","Lower down a little, with your back heel lifted.","⚠ Only a small dip. Keep your front knee from going past your toes."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"hinge-reach","name":"Hinge with reach","category":"hips","group":"Kalça & Bacak","sets":"10 reps","icon":"🦵","steps":["Knees soft, hands on the front of your thighs.","Lean forward and slide your hands down your thighs to just above your knees.","⚠ Keep your back straight. Come up slowly."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"calf-raise","name":"Calf raise","category":"hips","group":"Kalça & Bacak","sets":"12 reps","icon":"🦵","steps":["Hold the back of a chair for balance.","Slowly rise up onto your toes.","Lower slowly until your heels touch the floor."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"toe-raise","name":"Toe raise","category":"hips","group":"Kalça & Bacak","sets":"12 reps","icon":"🦵","steps":["Hold the back of a chair.","Lift the front of your feet and stand on your heels.","Lower slowly."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"lunge-stretch-reach","name":"Lunge stretch with overhead reach","category":"hips","group":"Kalça & Bacak","sets":"5 each side","icon":"🦵","steps":["Stand in a big step with your front knee slightly bent.","Raise the arm on the same side as your back leg up high and lean a little to the side.","⚠ Don't arch your back. Switch sides."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"inner-thigh-stretch","name":"Standing inner thigh stretch","category":"hips","group":"Kalça & Bacak","sets":"20 seconds each side","icon":"🦵","steps":["Stand with your feet wide apart.","Bend one knee and shift your weight onto it. Keep the other leg straight.","Feel the stretch along the inside of the straight leg. Switch sides."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"knee-to-chest-hip-stretch","name":"Standing knee hug","category":"hips","group":"Kalça & Bacak","sets":"10 seconds each leg","icon":"🦵","steps":["You can stand next to a wall for balance.","Lift one knee and hug it to your chest.","⚠ Sore knee? Hold under your thigh, not on the knee."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"cross-leg-side-stretch","name":"Crossed-leg outer hip stretch","category":"hips","group":"Kalça & Bacak","sets":"20 seconds each side","icon":"🦵","steps":["Cross one leg behind the other.","Push your hips out toward the side of the back leg and raise one arm overhead.","Lean a little to the other side. Switch sides."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"single-leg-balance","name":"Single-leg balance","category":"hips","group":"Kalça & Bacak","sets":"20 seconds each leg","icon":"🦵","steps":["Stand next to a wall or a chair.","Lift one foot a little, arms open to the sides.","Look ahead at one fixed spot. Switch legs."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"easy-tree-pose","name":"Easy tree pose","category":"hips","group":"Kalça & Bacak","sets":"20 seconds each leg","icon":"🦵","steps":["Stand next to a wall.","Rest one heel on the other ankle, knee turned out to the side.","Hands on your hips. Switch legs."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"neck-rotation","name":"Neck rotation","category":"upper","group":"Boyun, Omuz & Kol","sets":"5 each side","icon":"💪","steps":["Keep your back straight and your chin level with the floor.","Slowly turn your head to look over your shoulder.","Come back to center and turn to the other side."],"view":"head","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"neck-nod","name":"Neck flexion and extension","category":"upper","group":"Boyun, Omuz & Kol","sets":"8 reps","icon":"💪","steps":["Slowly lower your chin to your chest.","Come back up and look slightly upward.","Don't throw your head back."],"view":"head","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"neck-half-circle","name":"Neck half circles","category":"upper","group":"Boyun, Omuz & Kol","sets":"6 reps","icon":"💪","steps":["Tilt your ear toward your shoulder.","Roll your chin down across your chest to the other shoulder.","Only a half circle in front, never behind."],"view":"head","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"levator-stretch","name":"Levator scapulae stretch","category":"upper","group":"Boyun, Omuz & Kol","sets":"20 seconds each side","icon":"💪","steps":["Turn your head halfway to one side.","Lower your nose toward your armpit.","Feel the stretch at the back of your neck. Switch sides."],"view":"head","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"trap-stretch","name":"Upper trapezius stretch","category":"upper","group":"Boyun, Omuz & Kol","sets":"20 seconds each side","icon":"💪","steps":["Tilt your head to the left.","Reach your right hand down and out, like pushing the floor away.","Breathe, then switch sides."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"shoulder-shrugs","name":"Shoulder shrugs","category":"upper","group":"Boyun, Omuz & Kol","sets":"10 reps","icon":"💪","steps":["Let your arms hang loose at your sides.","Lift your shoulders up toward your ears.","Hold for a second and let them drop."],"view":"upper","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"shoulder-rolls-forward","name":"Shoulder rolls forward","category":"upper","group":"Boyun, Omuz & Kol","sets":"10 reps","icon":"💪","steps":["Lift your shoulders up toward your ears.","Roll them forward and down.","Keep the circle soft and smooth."],"view":"upper","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"y-raise","name":"Y raise","category":"upper","group":"Boyun, Omuz & Kol","sets":"10 reps","icon":"💪","steps":["Raise your straight arms up and out, like the letter Y.","Point your thumbs toward the ceiling.","Lower slowly."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"t-raise","name":"T raise","category":"upper","group":"Boyun, Omuz & Kol","sets":"10 reps","icon":"💪","steps":["Raise your straight arms out to the sides, up to shoulder height.","Squeeze your shoulder blades together a little.","Lower slowly."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"w-squeeze","name":"W squeeze","category":"upper","group":"Boyun, Omuz & Kol","sets":"10 reps","icon":"💪","steps":["Lift your elbows to shoulder height, forearms pointing up.","Pull your elbows down and back, like the letter W.","Squeeze your shoulder blades and hold for a second."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"goalpost-rotation","name":"Goalpost rotation","category":"upper","group":"Boyun, Omuz & Kol","sets":"10 reps","icon":"💪","steps":["Lift your elbows to shoulder height, forearms pointing forward.","Rotate your forearms up without moving your elbows.","Slowly bring them back forward."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"standing-snow-angel","name":"Standing snow angel","category":"upper","group":"Boyun, Omuz & Kol","sets":"8 reps","icon":"💪","steps":["Start in the W position, forearms pointing up.","Slide your arms up until they are almost straight.","Bring them back down and squeeze your shoulder blades."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"front-raise","name":"Front raise","category":"upper","group":"Boyun, Omuz & Kol","sets":"10 reps","icon":"💪","steps":["Hold your straight arms in front of your thighs.","Raise them to shoulder height.","Lower slowly, without swinging."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"lateral-raise","name":"Lateral raise","category":"upper","group":"Boyun, Omuz & Kol","sets":"10 reps","icon":"💪","steps":["Keep your elbows slightly bent.","Raise your arms out to the sides, up to shoulder height.","Lower slowly."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"overhead-reach","name":"Alternating overhead reach","category":"upper","group":"Boyun, Omuz & Kol","sets":"10 each side","icon":"💪","steps":["Reach one hand up as high as you can.","Let your body stretch a little to the other side.","Lower it and switch hands."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"self-hug","name":"Self hug upper-back stretch","category":"upper","group":"Boyun, Omuz & Kol","sets":"20 seconds","icon":"💪","steps":["Hug your shoulders with both arms.","Round your upper back a little and lower your chin.","Breathe into your back."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chest-opener-clasp","name":"Clasped-hands chest opener","category":"upper","group":"Boyun, Omuz & Kol","sets":"20 seconds","icon":"💪","steps":["Clasp your hands behind your back.","Pull your shoulders back and down.","Lift your chest and look forward."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"arms-back-chest-stretch","name":"Open-arms chest stretch","category":"upper","group":"Boyun, Omuz & Kol","sets":"20 seconds","icon":"💪","steps":["Open your arms out to the sides, a little above shoulder height.","Pull them back until you feel a stretch in your chest.","Breathe and release."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"pull-aparts","name":"Pull-aparts","category":"upper","group":"Boyun, Omuz & Kol","sets":"12 reps","icon":"💪","steps":["Hold your straight arms in front of you at shoulder height.","Open them out to the sides and squeeze your shoulder blades.","Slowly bring them back to the front."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"protraction-retraction","name":"Scapular push-pull","category":"upper","group":"Boyun, Omuz & Kol","sets":"12 reps","icon":"💪","steps":["Hold your straight arms in front of you.","Push forward, like reaching for something far away.","Pull back and squeeze your shoulder blades. Keep your arms straight."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"alternating-reach-forward","name":"Alternating forward reach","category":"upper","group":"Boyun, Omuz & Kol","sets":"10 each side","icon":"💪","steps":["Hold both arms out in front of you.","Reach one hand far forward, letting your shoulder and body turn a little.","Switch hands."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"punches","name":"Forward punches","category":"upper","group":"Boyun, Omuz & Kol","sets":"30 seconds","icon":"💪","steps":["Keep your knees soft and your hands near your chin.","Punch forward with one hand, then the other.","Keep a comfortable pace. Don't lock your elbow."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"overhead-punches","name":"Overhead punches","category":"upper","group":"Boyun, Omuz & Kol","sets":"30 seconds","icon":"💪","steps":["Make fists next to your shoulders.","Push one hand up to the ceiling, then the other.","Tighten your belly and don't arch your back."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"open-close-swings","name":"Open-close arm swings","category":"upper","group":"Boyun, Omuz & Kol","sets":"20 reps","icon":"💪","steps":["Open your arms out to the sides.","Bring them forward and cross them in front of your chest.","Open again. Keep it soft and flowing."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"arm-pendulum","name":"Arm pendulum swings","category":"upper","group":"Boyun, Omuz & Kol","sets":"30 seconds","icon":"💪","steps":["Keep your knees soft.","Swing your arms forward and back in opposite directions.","Keep your shoulders relaxed."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"sword-draw","name":"Sword draw","category":"upper","group":"Boyun, Omuz & Kol","sets":"10 each side","icon":"💪","steps":["Place your hand by the opposite hip, like holding a sword.","Draw it up and out on a diagonal, turning your palm outward.","Slowly return along the same path."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"biceps-curl","name":"Elbow curls","category":"upper","group":"Boyun, Omuz & Kol","sets":"12 reps","icon":"💪","steps":["Keep your elbows tucked to your sides.","Bend your elbows and bring your hands up to your shoulders.","Lower slowly until your arms are almost straight."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"triceps-kickback","name":"Triceps kickback","category":"upper","group":"Boyun, Omuz & Kol","sets":"12 reps","icon":"💪","steps":["Bend your knees slightly and lean forward with a straight back.","Keep your elbows tucked to your sides and pointing back.","Straighten your forearms back, then bend them again."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"forearm-rotation","name":"Forearm rotation","category":"upper","group":"Boyun, Omuz & Kol","sets":"15 reps","icon":"💪","steps":["Bend your elbows by your sides, forearms pointing forward.","Turn your palms up, then down.","Only your forearms turn. Your elbows stay in place."],"view":"upper","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"wrist-circles","name":"Wrist circles","category":"upper","group":"Boyun, Omuz & Kol","sets":"10 each direction","icon":"💪","steps":["Hold your forearms forward with loose fists.","Turn your wrists in full circles.","Especially good after a lot of typing."],"view":"upper","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"wrist-flexor-stretch","name":"Wrist flexor stretch","category":"upper","group":"Boyun, Omuz & Kol","sets":"20 seconds each hand","icon":"💪","steps":["Hold one straight arm forward, palm facing away from you and fingers up.","Use your other hand to gently pull the fingers back.","Switch hands."],"view":"upper","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"wrist-extensor-stretch","name":"Wrist extensor stretch","category":"upper","group":"Boyun, Omuz & Kol","sets":"20 seconds each hand","icon":"💪","steps":["Hold one straight arm forward, fingers pointing down.","Use your other hand to gently press on the back of your hand.","Switch hands."],"view":"upper","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"hands-to-shoulders","name":"Hands to shoulders and extend","category":"upper","group":"Boyun, Omuz & Kol","sets":"12 reps","icon":"💪","steps":["Open your arms out to the sides at shoulder height.","Bend your elbows and bring your fingertips to your shoulders.","Straighten your arms out again."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"elbow-circles","name":"Elbow circles","category":"upper","group":"Boyun, Omuz & Kol","sets":"8 each direction","icon":"💪","steps":["Put your fingertips on your shoulders, elbows pointing forward.","Draw big circles with your elbows.","Switch direction."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"mountain-pose-breath","name":"Mountain pose with breath","category":"yoga","group":"Yoga & Esneme","sets":"6 breaths","icon":"🌿","steps":["Stand tall with your feet hip-width apart.","Breathe in and raise your arms out to the sides and up.","Breathe out and slowly lower them back down."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"upward-salute-gentle","name":"Gentle upward salute","category":"yoga","group":"Yoga & Esneme","sets":"5 times","icon":"🌿","steps":["Stand in mountain pose.","Raise your arms up and lengthen your back.","Look up a little, without forcing a backbend.","⚠ If your lower back feels pressure, stay upright."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"standing-crescent-side-bend","name":"Standing crescent side bend","category":"yoga","group":"Yoga & Esneme","sets":"4 each side","icon":"🌿","steps":["Raise your arms up and press your palms together.","Slowly lean to one side, like a crescent moon.","Come back to center and lean to the other side."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-pose-gentle","name":"Gentle chair pose","category":"yoga","group":"Yoga & Esneme","sets":"5 breaths","icon":"🌿","steps":["Bring your feet together and bend your knees as if sitting down.","Push your hips back and keep your knees behind your toes.","Raise your arms and breathe.","⚠ Bend only a little if your knees are sensitive."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"chair-pose-prayer-twist","name":"Chair pose prayer twist","category":"yoga","group":"Yoga & Esneme","sets":"3 each side","icon":"🌿","steps":["Sink into a gentle chair pose with your palms together in front of your chest.","Turn your chest to one side.","Come back to center and turn to the other side.","⚠ Keep your knees pointing straight ahead. Twist only from the chest."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"warrior-1-gentle","name":"Warrior 1","category":"yoga","group":"Yoga & Esneme","sets":"5 breaths each side","icon":"🌿","steps":["Take a big step forward and keep your back leg straight.","Bend your front knee over your ankle.","Raise your arms and look ahead.","⚠ If your knee hurts, take a shorter step and bend less."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"warrior-2","name":"Warrior 2","category":"yoga","group":"Yoga & Esneme","sets":"5 breaths each side","icon":"🌿","steps":["Stand with your feet wide and turn your front foot out to the side.","Bend your front knee over your ankle.","Stretch your arms out to the sides and look out over your front hand.","⚠ Keep your knee over your ankle, not dropping inward."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"reverse-warrior-gentle","name":"Reverse warrior","category":"yoga","group":"Yoga & Esneme","sets":"3 each side","icon":"🌿","steps":["Start in warrior 2.","Sweep your front arm up and back in an arc.","Slide your back hand down your back leg.","Breathe, then return to warrior 2."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"extended-side-angle-gentle","name":"Gentle extended side angle","category":"yoga","group":"Yoga & Esneme","sets":"3 breaths each side","icon":"🌿","steps":["From warrior 2, rest your forearm on your front thigh.","Reach your other arm on a diagonal over your ear.","Make one long line from your back foot to your fingertips."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"triangle-pose","name":"Triangle pose","category":"yoga","group":"Yoga & Esneme","sets":"3 breaths each side","icon":"🌿","steps":["Stand with your legs wide and straight, front foot turned out to the side.","Lean over your front leg and rest your hand on your shin.","Reach your other arm up to the sky.","⚠ Keep your hand on your shin, not your knee. You don't need to reach the floor."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"warrior-3-gentle","name":"Gentle warrior 3","category":"yoga","group":"Yoga & Esneme","sets":"3 each leg","icon":"🌿","steps":["Stand on one leg with a soft knee.","Tip your body forward and lift your other leg behind you.","Reach your arms forward, making one line from your hands to your heel.","⚠ You can hold a wall or a chair for balance."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"pyramid-pose-soft","name":"Soft pyramid pose","category":"yoga","group":"Yoga & Esneme","sets":"3 breaths each side","icon":"🌿","steps":["Step one leg forward and one leg back, a medium step apart.","Fold over your front leg with a long back.","Bring your hands down to your shin and keep your knees soft.","⚠ Don't lock your front knee."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"goddess-pose-gentle","name":"Gentle goddess pose","category":"yoga","group":"Yoga & Esneme","sets":"5 times","icon":"🌿","steps":["Stand with your feet wide and toes turned out a little.","Bend your knees slightly and hold your arms in a W shape.","Slowly rise up and sink down.","⚠ Keep your knees in line with your toes and bend only a little."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"tree-pose-hands-heart","name":"Tree pose, hands at heart","category":"yoga","group":"Yoga & Esneme","sets":"20 seconds each leg","icon":"🌿","steps":["Stand on one leg.","Place your other foot on your shin, not on your knee.","Press your palms together in front of your chest and look at one fixed spot."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"yoga-tree-kickstand","name":"Kickstand tree pose","category":"yoga","group":"Yoga & Esneme","sets":"20 seconds each leg","icon":"🌿","steps":["Rest one heel against your other ankle, with your toes on the floor.","Turn your knee out to the side.","Raise your arms up like branches."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"standing-forward-fold-soft","name":"Soft standing forward fold","category":"yoga","group":"Yoga & Esneme","sets":"5 breaths","icon":"🌿","steps":["Bend your knees slightly.","Fold forward from your hips and let your head and arms hang.","Roll up slowly, one vertebra at a time.","⚠ Bent knees protect your lower back."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"sun-salutation-standing","name":"Sun salutation, standing part","category":"yoga","group":"Yoga & Esneme","sets":"4 rounds","icon":"🌿","steps":["Breathe in: arms up.","Breathe out: fold forward with soft knees.","Breathe in: lift halfway with a long back. Breathe out: fold again.","⚠ Keep your knees bent the whole time if your back is sensitive."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"sun-salutation-floor","name":"Sun salutation, floor part","category":"yoga","group":"Yoga & Esneme","sets":"3 rounds","icon":"🌿","steps":["From plank, lower your knees to the floor.","Lower down to your belly and lift into a baby cobra.","Push back into child's pose, then into downward dog.","⚠ You can skip the plank and start on your knees."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"table-to-downward-dog","name":"Downward dog from table","category":"yoga","group":"Yoga & Esneme","sets":"5 breaths","icon":"🌿","steps":["Start on your hands and knees.","Lift your hips up and back into an upside-down V.","Keep your knees soft. Your heels don't have to touch the floor.","⚠ If your wrists hurt, rest in child's pose."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"downward-dog-pedal","name":"Pedaling downward dog","category":"yoga","group":"Yoga & Esneme","sets":"8 each leg","icon":"🌿","steps":["Start in downward dog.","Bend one knee and lower your other heel.","Switch legs slowly, like walking in place."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"plank-on-knees","name":"Plank on knees","category":"yoga","group":"Yoga & Esneme","sets":"20 seconds","icon":"🌿","steps":["Place your hands under your shoulders and your knees on the floor.","Make a straight line from your head to your knees.","Draw your belly in and breathe.","⚠ Put a cushion under your knees."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"plank-full","name":"Plank","category":"yoga","group":"Yoga & Esneme","sets":"20 seconds","icon":"🌿","steps":["Place your hands under your shoulders and stretch your legs straight back.","Make one straight line from your head to your heels.","Don't let your hips sag or pop up.","⚠ Wrists hurt? Do it on your forearms or your knees."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"plank-to-down-dog-flow","name":"Plank to downward dog flow","category":"yoga","group":"Yoga & Esneme","sets":"6 times","icon":"🌿","steps":["Start in plank.","Breathe out and push your hips up into downward dog.","Breathe in and come back to plank."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"baby-cobra","name":"Baby cobra","category":"yoga","group":"Yoga & Esneme","sets":"6 times","icon":"🌿","steps":["Lie on your belly with your hands next to your chest.","Lift only your chest and keep your elbows close to your body.","Keep your shoulders away from your ears.","⚠ Lift only a little, with no pressure in your lower back."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"cobra-to-child-flow","name":"Cobra to child flow","category":"yoga","group":"Yoga & Esneme","sets":"5 times","icon":"🌿","steps":["Baby cobra: lift your chest a little.","Push back into child's pose.","Breathe, then slowly come back down to your belly."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"locust-gentle","name":"Gentle locust","category":"yoga","group":"Yoga & Esneme","sets":"6 times","icon":"🌿","steps":["Lie on your belly with your arms along your body.","Lift your chest and legs a little at the same time.","Look at the floor, hold for two seconds, and lower down.","⚠ Lifting just an inch or two is enough."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"yoga-child-pose","name":"Child's pose","category":"yoga","group":"Yoga & Esneme","sets":"30 seconds","icon":"🌿","steps":["Kneel and sit back on your heels.","Lower your forehead to the floor and reach your arms forward.","Breathe into your back.","⚠ Put a cushion between your bottom and your heels if your knees hurt."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"yoga-cat-cow","name":"Cat-cow","category":"yoga","group":"Yoga & Esneme","sets":"8 times","icon":"🌿","steps":["Get on your hands and knees.","Breathe out: round your back up and tuck your chin to your chest.","Breathe in: let your belly drop and look up a little."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"low-lunge-kneeling","name":"Kneeling low lunge","category":"yoga","group":"Yoga & Esneme","sets":"5 breaths each side","icon":"🌿","steps":["Step one leg forward and rest your back knee on the floor.","Press your hips forward a little.","Raise your arms.","⚠ Put a cushion under your back knee."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"gate-pose-kneeling","name":"Gate pose","category":"yoga","group":"Yoga & Esneme","sets":"3 each side","icon":"🌿","steps":["Kneel upright on your knees.","Stretch one leg out to the side.","Lean toward it and arc your other arm over your head.","⚠ Put a cushion under your knee."],"view":"full","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"reclined-pigeon","name":"Reclined pigeon","category":"yoga","group":"Yoga & Esneme","sets":"30 seconds each side","icon":"🌿","steps":["Lie on your back with your knees bent.","Cross one ankle over your other knee.","Draw your legs toward your chest until you feel a stretch in your buttock.","⚠ A gentle version of pigeon pose, with no pressure on your knees."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"bridge-pose-hold","name":"Bridge pose","category":"yoga","group":"Yoga & Esneme","sets":"5 times","icon":"🌿","steps":["Lie on your back with your feet flat on the floor.","Slowly lift your hips.","Hold for 3 breaths, then roll down one vertebra at a time.","⚠ Lift your hips only to a straight line, no higher."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"yoga-happy-baby","name":"Happy baby","category":"yoga","group":"Yoga & Esneme","sets":"30 seconds","icon":"🌿","steps":["Lie on your back.","Bring your knees up beside your belly with the soles of your feet facing the ceiling.","Hold your feet and rock gently."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"supine-knee-twist","name":"Supine knee twist","category":"yoga","group":"Yoga & Esneme","sets":"30 seconds each side","icon":"🌿","steps":["Lie on your back with your arms out to the sides.","Let your bent knees drop to one side.","Look the other way and keep your shoulders on the floor."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"legs-up-pose","name":"Legs up pose","category":"yoga","group":"Yoga & Esneme","sets":"1 minute","icon":"🌿","steps":["Lie on your back.","Raise your legs toward the ceiling with soft knees.","You can rest your legs against a wall.","Breathe and relax."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"reclined-butterfly","name":"Reclined butterfly","category":"yoga","group":"Yoga & Esneme","sets":"1 minute","icon":"🌿","steps":["Lie on your back.","Press the soles of your feet together and let your knees fall open.","Rest your arms loosely by your sides and breathe.","⚠ Put a cushion under each knee if the stretch is too much."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"savasana-rest","name":"Savasana","category":"yoga","group":"Yoga & Esneme","sets":"2 minutes","icon":"🌿","steps":["Lie on your back with your arms and legs slightly apart.","Close your eyes.","Breathe slowly and relax your whole body."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"yoga-seated-fold-soft","name":"Soft seated forward fold","category":"yoga","group":"Yoga & Esneme","sets":"30 seconds","icon":"🌿","steps":["Sit with your legs out in front and your knees slightly bent.","Lengthen your back and fold forward from your hips.","Rest your hands on your shins without pulling.","⚠ Don't force your back to round. Bent knees are better."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"head-to-knee-soft","name":"Soft head to knee","category":"yoga","group":"Yoga & Esneme","sets":"20 seconds each side","icon":"🌿","steps":["Keep one leg straight and place your other foot against your inner thigh.","Turn slightly toward the straight leg.","Fold forward with a long back."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"butterfly-seated-lean","name":"Seated butterfly","category":"yoga","group":"Yoga & Esneme","sets":"30 seconds","icon":"🌿","steps":["Press the soles of your feet together and let your knees open to the sides.","Sit tall with your hands on your ankles.","Lean forward a little with a straight back."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"wide-leg-seated-fold","name":"Wide-leg seated fold","category":"yoga","group":"Yoga & Esneme","sets":"30 seconds","icon":"🌿","steps":["Sit with your legs spread wide to the sides.","Place your hands on the floor in front of you.","Walk your hands forward a little with a long back.","⚠ Bend your knees slightly if you feel a pull behind them."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"easy-seat-breath-arms","name":"Easy seat with arm breath","category":"yoga","group":"Yoga & Esneme","sets":"6 breaths","icon":"🌿","steps":["Sit cross-legged with a tall back.","Breathe in: raise your arms up.","Breathe out: lower your hands to your knees."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"seated-side-bend-cross","name":"Seated side bend","category":"yoga","group":"Yoga & Esneme","sets":"4 each side","icon":"🌿","steps":["Sit cross-legged.","Raise one arm up and over your head toward the other side.","Rest your other hand on the floor for support."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"seated-twist-easy","name":"Easy seated twist","category":"yoga","group":"Yoga & Esneme","sets":"3 each side","icon":"🌿","steps":["Sit cross-legged with a long back.","Put your right hand on your left knee and your left hand behind you.","Breathe out as you twist, looking over your shoulder.","Switch sides."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"yoga-easy-boat","name":"Easy boat pose","category":"yoga","group":"Yoga & Esneme","sets":"15 seconds","icon":"🌿","steps":["Sit with your knees bent.","Lean back a little and lift your feet.","Reach your arms forward and keep your back straight.","⚠ You can keep your toes on the floor."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"},{"id":"staff-pose-yoga","name":"Staff pose","category":"yoga","group":"Yoga & Esneme","sets":"5 breaths","icon":"🌿","steps":["Sit with your legs straight out in front.","Place your hands by your hips and press down lightly.","Sit tall and pull your toes toward you."],"view":"floor","kind":"mobility","isNew":true,"source":"Desk Break · MIT"}];
